package worker

import("context";"path/filepath";"testing";"time";"github.com/11DingKing/silvercare-coordination/internal/clock";"github.com/11DingKing/silvercare-coordination/internal/domain";storesqlite "github.com/11DingKing/silvercare-coordination/internal/store/sqlite")

func TestFailedEscalationExpiryPreservesBatch(t *testing.T){ctx:=context.Background();now:=time.Date(2026,8,24,8,0,0,0,time.UTC);repo,e:=storesqlite.Open(ctx,filepath.Join(t.TempDir(),"w.db"));if e!=nil{t.Fatal(e)};defer repo.Close();repo.Migrate(ctx);repo.EnsureDistrict(ctx,nil,storesqlite.DistrictBudget{ID:"d",Name:"街道",Timezone:"Asia/Shanghai",MonthlyCents:1000000,Version:1,CreatedAt:now,UpdatedAt:now});exec:=func(q string,a ...any){if _,e:=repo.DB().ExecContext(ctx,q,a...);e!=nil{t.Fatal(e)}};ts:=now.Add(-time.Hour).Format(time.RFC3339Nano);created:=now.Add(-2*time.Hour).Format(time.RFC3339Nano);exec(`INSERT INTO residents(id,district_id,external_ref,full_name,birth_date,household_id,consent_status,version,created_at,updated_at) VALUES('r','d','ext','老人','1940-01-01','h','granted',1,?,?)`,created,created);for _,id:=range []string{"e1","e2"}{exec(`INSERT INTO escalations(id,district_id,resident_id,visit_id,severity,status,summary,acknowledgement_due_at,acknowledged_by,acknowledged_at,resolved_at,version,created_at,updated_at) VALUES(?,?,?,NULL,'urgent','open','help',?,NULL,NULL,NULL,1,?,?)`,id,"d","r",ts,created,created)};exec(`CREATE TRIGGER reject_second BEFORE UPDATE ON escalations WHEN NEW.id='e2' AND NEW.status='expired' BEGIN SELECT RAISE(ABORT,'second failure'); END`);m:=NewMaintenance(repo,clock.NewFixed(now));if e:=m.ExpireEscalations(ctx,domain.WorkerJob{});e==nil{t.Fatal("expected failure")};first,_:=repo.EscalationByID(ctx,nil,"e1","d");second,_:=repo.EscalationByID(ctx,nil,"e2","d");if first.Status!=domain.EscalationOpen||first.Version!=1||second.Status!=domain.EscalationOpen{t.Errorf("batch=%s/%d,%s/%d",first.Status,first.Version,second.Status,second.Version)}}
